#pragma once

#include <cstdint>

namespace zet::grid {

/// Returns the display width of a Unicode codepoint, following wcwidth(3).
///
/// -1   C0/DEL/C1 controls
///  0   non-spacing marks, format characters (zero-width)
///  1   most characters
///  2   East Asian Wide (W) and Fullwidth (F) per Unicode 16.0.0
///
/// Tables generated by tools/gen_unicode_width.py from Unicode 16.0.0 data.
/// Non-UTF-8 bytes that pass through the parser as raw octets may not match
/// these widths; cursor drift is documented in design.md §9.
[[nodiscard]] int Wcwidth(char32_t cp) noexcept;

/// East Asian Ambiguous (EAW A): one column here, two on a terminal set to
/// wide ambiguous, so the column of whatever follows is not certain. Includes
/// Cyrillic, box drawing, Greek and private use.
[[nodiscard]] bool IsAmbiguousWidth(char32_t cp) noexcept;

/// Private use: U+E000-F8FF and planes 15-16. Ambiguous in the width table;
/// terminals draw powerline and Nerd Fonts glyphs here in one or two columns.
[[nodiscard]] constexpr bool IsPrivateUse(char32_t cp) noexcept {
    return (cp >= 0xE000 && cp <= 0xF8FF) || (cp >= 0xF0000 && cp <= 0xFFFFD) ||
           (cp >= 0x100000 && cp <= 0x10FFFD);
}

/// A codepoint with an emoji variation sequence (emoji-variation-sequences.txt:
/// base + VS16 is drawn as an emoji), among them text glyphs of width 1 such as
/// U+2601 and U+2764 that some terminals then draw two columns wide.
[[nodiscard]] bool HasEmojiVariation(char32_t cp) noexcept;

/// A codepoint whose width depends on the Unicode version of the terminal's
/// table: a wide one added after Unicode 9.0 (an older table draws it in one
/// column) or an unassigned one in an emoji block (a newer table may draw it in
/// two). Table generated from DerivedAge.txt of Unicode 16.0.0.
[[nodiscard]] bool IsVersionVolatileWidth(char32_t cp) noexcept;

/// A codepoint that glues to the glyph before it into a cluster some terminals
/// draw in a different width than a per-codepoint wcwidth gives: ZWJ, the
/// variation selectors VS15 and VS16 and the emoji skin tone modifiers.
[[nodiscard]] bool IsClusterJoiner(char32_t cp) noexcept;

}  // namespace zet::grid
